import json, os, uuid
ROOT='/mnt/data/v92_work'
compdir=os.path.join(ROOT,'src/views/components/home')
os.makedirs(compdir,exist_ok=True)

def w(name,txt):
    open(os.path.join(compdir,name+'.twig'),'w',encoding='utf-8').write(txt)

w('video-hero','''{% set slides = component.items|default([]) %}\n{% if slides|length %}<section component-id="{{ componentId }}" class="s-block hn-vhero">{% for item in slides %}<article class="hn-vhero__slide">{% if item.video %}<video class="hn-vhero__media" autoplay muted loop playsinline preload="metadata" poster="{{ item.poster }}"><source src="{{ item.video }}"></video>{% elseif item.image %}<img class="hn-vhero__media" src="{{ item.image }}" alt="{{ item.title }}" loading="lazy">{% endif %}<div class="hn-vhero__overlay"><span class="hn-eyebrow">{{ item.eyebrow }}</span><h2>{{ item.title }}</h2><p>{{ item.text }}</p>{% if item.url %}<a class="hn-btn hn-btn--gold" href="{{ item.url }}">{{ item.button_text|default(trans('hn.v92.shop_now')) }}</a>{% endif %}</div></article>{% endfor %}</section>{% endif %}''')
w('stories','''{% set items = component.items|default([]) %}\n{% if items|length %}<section component-id="{{ componentId }}" class="s-block hn-stories"><div class="s-block__title"><h2>{{ component.title|default(trans('hn.v92.stories_title')) }}</h2></div><div class="hn-stories__track">{% for item in items %}<a class="hn-story" href="{{ item.url|default('#') }}" {% if item.url %}target="_blank" rel="noopener noreferrer"{% endif %}><span class="hn-story__ring"><img src="{{ item.image }}" alt="{{ item.title }}" loading="lazy"></span><span>{{ item.title }}</span></a>{% endfor %}</div></section>{% endif %}''')
w('influencer-videos','''{% set items = component.items|default([]) %}\n{% if items|length %}<section component-id="{{ componentId }}" class="s-block hn-influencers"><div class="s-block__title"><h2>{{ component.title|default(trans('hn.v92.influencer_title')) }}</h2></div><div class="hn-influencers__grid">{% for item in items %}<article class="hn-influencer">{% if item.video %}<video controls muted playsinline preload="metadata" poster="{{ item.poster }}"><source src="{{ item.video }}"></video>{% else %}<img src="{{ item.image }}" alt="{{ item.name }}" loading="lazy">{% endif %}<div class="hn-influencer__body"><strong>{{ item.name }}</strong><p>{{ item.caption }}</p>{% if item.url %}<a href="{{ item.url }}" target="_blank" rel="noopener noreferrer">{{ trans('hn.v92.watch') }}</a>{% endif %}</div></article>{% endfor %}</div></section>{% endif %}''')
w('store-statistics','''{% set items = component.items|default([]) %}\n{% if items|length %}<section component-id="{{ componentId }}" class="s-block hn-stats"><div class="hn-stats__grid">{% for item in items %}<article class="hn-stat"><strong>{{ item.value }}</strong><span>{{ item.label }}</span></article>{% endfor %}</div></section>{% endif %}''')
w('branches-map','''{% set items = component.items|default([]) %}\n{% if items|length %}<section component-id="{{ componentId }}" class="s-block hn-branches"><div class="s-block__title"><h2>{{ component.title|default(trans('hn.v92.branches_title')) }}</h2></div><div class="hn-branches__grid">{% for item in items %}<article class="hn-branch"><div><h3>{{ item.name }}</h3><p>{{ item.address }}</p><small>{{ item.hours }}</small></div>{% if item.map_url %}<a class="hn-btn hn-btn--outline" href="{{ item.map_url }}" target="_blank" rel="noopener noreferrer">{{ trans('hn.v92.open_map') }}</a>{% endif %}</article>{% endfor %}</div></section>{% endif %}''')
w('wholesale-offers','''{% set items = component.items|default([]) %}\n{% if items|length %}<section component-id="{{ componentId }}" class="s-block hn-wholesale"><div class="s-block__title"><h2>{{ component.title|default(trans('hn.v92.wholesale_title')) }}</h2></div><div class="hn-wholesale__table"><div class="hn-wholesale__row hn-wholesale__head"><span>{{ trans('hn.v92.quantity') }}</span><span>{{ trans('hn.v92.discount') }}</span><span>{{ trans('hn.v92.price') }}</span></div>{% for item in items %}<div class="hn-wholesale__row"><span>{{ item.quantity }}</span><span>{{ item.discount }}</span><strong>{{ item.price }}</strong></div>{% endfor %}</div></section>{% endif %}''')
w('smart-recommendations','''{% set items = component.items|default([]) %}\n{% if items|length %}<section component-id="{{ componentId }}" class="s-block hn-recommendations"><div class="s-block__title"><h2>{{ component.title|default(trans('hn.v92.recommendations_title')) }}</h2></div><div class="hn-recommendations__grid">{% for item in items %}<article class="hn-rec"><a href="{{ item.url|default('#') }}"><img src="{{ item.image }}" alt="{{ item.name }}" loading="lazy"><div><h3>{{ item.name }}</h3><span>{{ item.price }}</span></div></a></article>{% endfor %}</div></section>{% endif %}''')
w('compare-products','''{% set items = component.items|default([]) %}\n{% if items|length %}<section component-id="{{ componentId }}" class="s-block hn-compare" data-hn-compare><div class="s-block__title"><h2>{{ component.title|default(trans('hn.v92.compare_title')) }}</h2><p>{{ trans('hn.v92.compare_hint') }}</p></div><div class="hn-compare__grid">{% for item in items %}<label class="hn-compare-card"><input type="checkbox" data-hn-compare-item value="{{ loop.index }}"><img src="{{ item.image }}" alt="{{ item.name }}" loading="lazy"><strong>{{ item.name }}</strong><span>{{ item.price }}</span></label>{% endfor %}</div><button type="button" class="hn-btn hn-btn--gold" data-hn-compare-open disabled>{{ trans('hn.v92.compare_action') }}</button><div class="hn-compare__result" data-hn-compare-result hidden></div></section>{% endif %}''')

# append JS for compare
js=os.path.join(ROOT,'src/assets/js/components.js')
s=open(js,encoding='utf-8').read()
s += '''\n(function(){document.querySelectorAll('[data-hn-compare]').forEach(function(root){var boxes=root.querySelectorAll('[data-hn-compare-item]'),btn=root.querySelector('[data-hn-compare-open]'),out=root.querySelector('[data-hn-compare-result]');function sync(){var checked=[].filter.call(boxes,function(x){return x.checked});btn.disabled=checked.length<2||checked.length>4; if(checked.length===0){out.hidden=true;out.innerHTML='';}else{out.hidden=false;out.innerHTML='<div class="hn-compare__count">'+checked.length+' '+(checked.length===1?'item':'items')+'</div>';}}boxes.forEach(function(x){x.addEventListener('change',sync)});btn.addEventListener('click',function(){var checked=[].filter.call(boxes,function(x){return x.checked});if(checked.length<2||checked.length>4)return;out.hidden=false;out.innerHTML='<div class="hn-compare__selected">'+checked.map(function(x){var card=x.closest('.hn-compare-card');return '<span>'+card.querySelector('strong').textContent+'</span>'}).join('')+'</div>';});});})();\n'''
open(js,'w',encoding='utf-8').write(s)

# CSS append
css=os.path.join(ROOT,'src/assets/styles/components.css')
with open(css,'a',encoding='utf-8') as f:
 f.write('''\n/* V9.2 */\n.hn-vhero{position:relative;overflow:hidden;border-radius:24px;min-height:420px}.hn-vhero__slide{position:relative;min-height:420px;display:flex;align-items:center}.hn-vhero__media{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.hn-vhero__overlay{position:relative;z-index:1;max-width:620px;padding:56px;margin-inline-start:5%;color:#fff;text-shadow:0 2px 12px rgba(0,0,0,.35)}.hn-vhero__overlay h2{font-size:clamp(2rem,4vw,4rem);margin:.35rem 0}.hn-vhero__overlay p{font-size:1.05rem}.hn-eyebrow{font-weight:700}.hn-stories__track{display:flex;gap:20px;overflow:auto;padding:8px 4px}.hn-story{min-width:90px;text-align:center;color:inherit;text-decoration:none}.hn-story__ring{display:block;padding:3px;border-radius:50%;background:linear-gradient(135deg,#c9a24b,#fff,#c9a24b);margin:auto auto 8px;width:76px;height:76px}.hn-story img{width:100%;height:100%;object-fit:cover;border-radius:50%;display:block}.hn-influencers__grid,.hn-recommendations__grid,.hn-compare__grid,.hn-branches__grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.hn-influencer,.hn-rec,.hn-compare-card,.hn-branch{border:1px solid var(--border-color,#e8e8e8);border-radius:18px;overflow:hidden;background:var(--color-background,#fff)}.hn-influencer video,.hn-influencer img,.hn-rec img,.hn-compare-card img{display:block;width:100%;aspect-ratio:4/5;object-fit:cover}.hn-influencer__body,.hn-rec div,.hn-branch{padding:14px}.hn-stats__grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.hn-stat{text-align:center;padding:24px;border-radius:18px;background:rgba(201,162,75,.09)}.hn-stat strong{display:block;font-size:2rem}.hn-stat span{opacity:.75}.hn-branch{display:flex;justify-content:space-between;gap:14px;align-items:end}.hn-wholesale__table{border:1px solid var(--border-color,#e8e8e8);border-radius:16px;overflow:hidden}.hn-wholesale__row{display:grid;grid-template-columns:1fr 1fr 1fr;padding:14px;border-top:1px solid var(--border-color,#e8e8e8)}.hn-wholesale__row:first-child{border-top:0}.hn-wholesale__head{font-weight:700;background:rgba(201,162,75,.08)}.hn-compare-card{display:flex;flex-direction:column;gap:8px;padding:0 0 14px}.hn-compare-card input{margin:12px 12px 0}.hn-compare-card strong,.hn-compare-card span{padding-inline:12px}.hn-compare__result{margin-top:16px;padding:16px;border-radius:16px;background:rgba(201,162,75,.08)}.hn-compare__selected{display:flex;flex-wrap:wrap;gap:8px}.hn-compare__selected span{padding:8px 12px;border-radius:999px;background:#fff;border:1px solid var(--border-color,#e8e8e8)}@media(max-width:768px){.hn-vhero,.hn-vhero__slide{min-height:360px}.hn-vhero__overlay{padding:32px 24px;margin:0}.hn-influencers__grid,.hn-recommendations__grid,.hn-compare__grid{grid-template-columns:repeat(2,minmax(0,1fr))}.hn-branches__grid{grid-template-columns:1fr}.hn-stats__grid{grid-template-columns:repeat(2,1fr)}}\n''')

# locales
for lang in ['ar','en']:
 p=os.path.join(ROOT,'src/locales',lang+'.json'); d=json.load(open(p,encoding='utf-8'))
 d.setdefault('hn',{}).setdefault('v92',{})
 if lang=='ar':
  vals={'shop_now':'تسوق الآن','stories_title':'قصص المتجر','influencer_title':'إطلالات وتجارب','watch':'شاهد الآن','branches_title':'فروعنا','open_map':'فتح الموقع','wholesale_title':'عروض الجملة','quantity':'الكمية','discount':'الخصم','price':'السعر','recommendations_title':'قد يعجبك أيضًا','compare_title':'قارن المنتجات','compare_hint':'اختر من 2 إلى 4 منتجات للمقارنة','compare_action':'عرض المقارنة'}
 else:
  vals={'shop_now':'Shop now','stories_title':'Store Stories','influencer_title':'Looks & Experiences','watch':'Watch now','branches_title':'Our branches','open_map':'Open location','wholesale_title':'Wholesale offers','quantity':'Quantity','discount':'Discount','price':'Price','recommendations_title':'You may also like','compare_title':'Compare products','compare_hint':'Choose 2 to 4 products to compare','compare_action':'View comparison'}
 d['hn']['v92']=vals
 open(p,'w',encoding='utf-8').write(json.dumps(d,ensure_ascii=False,indent=2))

# Twilight metadata
p=os.path.join(ROOT,'twilight.json'); d=json.load(open(p,encoding='utf-8'))
d['version']='9.2.0'; d['description']['ar']=d['description']['ar'].replace('9.1','9.2'); d['description']['en']=d['description']['en'].replace('9.1','9.2')
# settings append
existing={x.get('id') for x in d.get('settings',[])}
newsettings=[
('hn_enable_dark_mode','تفعيل الوضع الداكن','Enable dark mode'),('hn_enable_v92_stories','تفعيل قصص المتجر','Enable store stories'),('hn_enable_v92_video_hero','تفعيل Hero بالفيديو','Enable video hero'),('hn_enable_v92_influencers','تفعيل تجارب المؤثرين','Enable influencer experiences'),('hn_enable_v92_statistics','تفعيل إحصائيات المتجر','Enable store statistics'),('hn_enable_v92_branches','تفعيل الفروع والخريطة','Enable branches and map'),('hn_enable_v92_wholesale','تفعيل عروض الجملة','Enable wholesale offers'),('hn_enable_v92_compare','تفعيل مقارنة المنتجات','Enable product comparison')]
for i,(id,ar,en) in enumerate(newsettings):
 if id not in existing:
  d['settings'].append({'id':id,'type':'boolean','format':'switch','label':ar,'description':en,'icon':'sicon-toggle-off','required':False,'value':True,'selected':True})
# components append
paths={c.get('path') for c in d.get('components',[])}
def field_text(id,label,multi=False,maxlen=200,fmt='text'):
 x={'type':'string','format':fmt,'id':id,'label':label,'value':None,'required':False,'maxLength':maxlen}
 if multi:x['multilanguage']=True
 return x
new=[]
new.append({'key':str(uuid.uuid4()),'title':{'ar':'Hero بالفيديو','en':'Video Hero'},'icon':'sicon-video','path':'home.video-hero','fields':[{'id':'items','type':'collection','format':'collection','required':False,'minLength':1,'maxLength':5,'label':'شرائح Hero','item_label':'شريحة','value':[],'fields':[field_text('items.video','رابط الفيديو',False,500),field_text('items.image','الصورة البديلة',False,500,'image'),field_text('items.poster','صورة الغلاف',False,500,'image'),field_text('items.eyebrow','العنوان الصغير',True,60),field_text('items.title','العنوان',True,100),field_text('items.text','الوصف',True,180),field_text('items.button_text','نص الزر',True,40),field_text('items.url','الرابط',False,500)]}]})
