new.append({'key':str(uuid.uuid4()),'title':{'ar':'تجارب المؤثرين','en':'Influencer Experiences'},'icon':'sicon-video','path':'home.influencer-videos','fields':[field_text('title','العنوان',True,100),{'id':'items','type':'collection','format':'collection','required':False,'minLength':1,'maxLength':8,'label':'المقاطع','item_label':'مقطع','value':[],'fields':[field_text('items.video','رابط الفيديو',False,500),field_text('items.image','الصورة',False,500,'image'),field_text('items.poster','الغلاف',False,500,'image'),field_text('items.name','الاسم',True,80),field_text('items.caption','الوصف',True,160),field_text('items.url','الرابط',False,500)]}]})
new.append({'key':str(uuid.uuid4()),'title':{'ar':'إحصائيات المتجر','en':'Store Statistics'},'icon':'sicon-chart','path':'home.store-statistics','fields':[{'id':'items','type':'collection','format':'collection','required':False,'minLength':1,'maxLength':8,'label':'الإحصائيات','item_label':'إحصائية','value':[],'fields':[field_text('items.value','القيمة',False,30),field_text('items.label','الوصف',True,80)]}]})
new.append({'key':str(uuid.uuid4()),'title':{'ar':'الفروع والخريطة','en':'Branches & Map'},'icon':'sicon-location','path':'home.branches-map','fields':[field_text('title','العنوان',True,100),{'id':'items','type':'collection','format':'collection','required':False,'minLength':1,'maxLength':12,'label':'الفروع','item_label':'فرع','value':[],'fields':[field_text('items.name','اسم الفرع',True,80),field_text('items.address','العنوان',True,160),field_text('items.hours','ساعات العمل',True,100),field_text('items.map_url','رابط الخريطة',False,500)]}]})
