new.append({'key':str(uuid.uuid4()),'title':{'ar':'توصيات ذكية','en':'Smart Recommendations'},'icon':'sicon-products','path':'home.smart-recommendations','fields':[field_text('title','العنوان',True,100),{'id':'items','type':'collection','format':'collection','required':False,'minLength':1,'maxLength':12,'label':'المنتجات','item_label':'منتج','value':[],'fields':[field_text('items.image','الصورة',False,500,'image'),field_text('items.name','اسم المنتج',True,100),field_text('items.price','السعر',True,50),field_text('items.url','الرابط',False,500)]}]})
new.append({'key':str(uuid.uuid4()),'title':{'ar':'مقارنة المنتجات','en':'Compare Products'},'icon':'sicon-list','path':'home.compare-products','fields':[field_text('title','العنوان',True,100),{'id':'items','type':'collection','format':'collection','required':False,'minLength':2,'maxLength':8,'label':'المنتجات','item_label':'منتج','value':[],'fields':[field_text('items.image','الصورة',False,500,'image'),field_text('items.name','اسم المنتج',True,100),field_text('items.price','السعر',True,50)]}]})
for c in new:
 if c['path'] not in paths: d['components'].append(c)
d['name']={'ar':'همسة نبض','en':'Hamsa Nabd'}
